CREATE TRIGGER TRG_LINEREGU_UpdateParams
ON LINEREGU
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CODART VARCHAR(15);
  DECLARE @MP VARCHAR(2);
    DECLARE @LOTE VARCHAR(25);
    DECLARE @PARAM1 VARCHAR(30);
    DECLARE @PARAM2 VARCHAR(30);
  DECLARE @FECHA DATETIME;
  DECLARE @IDREG FLOAT;
  DECLARE @IDLIN FLOAT;


  SELECT @IDREG=IDREG,@IDLIN=IDLIN,@MP=LEFT(CODART,2),@LOTE=LOTE,@CODART=CODART FROM INSERTED;

  IF @IDREG>0 AND @MP='MP'
   
    SELECT TOP 1 @PARAM1=COALESCE(PARAM1,''), @PARAM2=COALESCE(PARAM2,'') 
    FROM LINEFACT L 
    WHERE IDFACC>0
    AND CODART = @CODART
    AND LOTE = @LOTE
    ORDER BY FECHA;


    -- Si se obtuvo algún valor, actualizar en LINEFACT
      UPDATE LINEREGU
      SET PARAM1 = @PARAM1, PARAM2 = @PARAM2, PARAM3=@LOTE
      WHERE IDLIN = @IDLIN; 
  END;

CREATE TRIGGER TRG_LINEALBA_UpdatePARAMS ON LINEALBA AFTER INSERT, UPDATE AS BEGIN SET NOCOUNT ON;
DECLARE @CODART VARCHAR(15); DECLARE @LOTE VARCHAR(25); DECLARE @PARAM1 VARCHAR(30); DECLARE @PARAM2 VARCHAR(30); DECLARE @FECHA DATETIME; DECLARE @IDALBV FLOAT;
SELECT @IDALBV=IDALBV FROM INSERTED;
IF @IDALBV>0 -- Consultar el primer registro en LINEREGU, ordenado por fecha descendente, con coincidencia de CODART y LOTE SELECT TOP 1 @FECHA=FECHA,@PARAM1=PARAM1, @PARAM2=PARAM2 FROM ( SELECT FECHA,COALESCE(PARAM1,'') PARAM1, COALESCE(PARAM2,'') PARAM2 FROM LINEREGU (NOLOCK) WHERE CODART = (SELECT CODART FROM inserted) AND LOTE = (SELECT LOTE FROM inserted)
UNION ALL
SELECT M.FECDOC FECHA,COALESCE(L.PARAM1,'') PARAM1, COALESCE(L.PARAM2,'') PARAM2 FROM MOVSTOCKS M (NOLOCK) LEFT OUTER JOIN LINEFACT L (NOLOCK) ON L.IDLIN=M.IDLIN WHERE M.TIPDOC='FC' AND M.CODART = (SELECT CODART FROM inserted) AND M.LOTE = (SELECT LOTE FROM inserted) ) AS TABLA ORDER BY FECHA DESC;
-- Si se obtuvo algún valor, actualizar en LINEFACT IF @PARAM1>'' BEGIN UPDATE LINEALBA SET PARAM1 = @PARAM1, PARAM2 = @PARAM2 WHERE IDALBV = (SELECT IDALBV FROM inserted) AND CODART = (SELECT CODART FROM inserted) AND LOTE = (SELECT LOTE FROM inserted); END
UPDATE L SET L.PARAM3 = L.LOTE FROM LINEALBA L WHERE IDALBV = @IDALBV; END;
